Utility helpers for the Google ADK scorer integration.

These functions convert MLflow scorer inputs into the ``Invocation`` objects
expected by Google ADK's evaluator interface and extract tool-call information
from MLflow traces.
"""

from __future__ import annotations

from typing import Any

from mlflow.entities.span import SpanType
from mlflow.entities.trace import Trace
from mlflow.exceptions import MlflowException
from mlflow.genai.utils.trace_utils import parse_inputs_to_str, parse_outputs_to_str


def check_adk_installed() -> None:
    """Check whether the ``google-adk`` package is installed and raise if not."""
    try:
        import google.adk  # noqa: F401
    except ImportError:
        raise MlflowException.invalid_parameter_value(
            "Google ADK scorers require the 'google-adk' package. "
            "Install it with: pip install google-adk"
        )


def _to_text(value: Any) -> str:
    """Best-effort conversion of an arbitrary scorer value to a string."""
    if value is None:
        return ""
    if isinstance(value, str):
        return value
    return parse_inputs_to_str(value)


def _extract_actual_tool_calls(
    expectations: dict[str, Any] | None,
    trace: Trace | None,
) -> list[dict[str, Any]]:
    """Extract the list of actual tool calls as dicts with ``name`` and ``args`` keys.

    Priority order:

    1. ``expectations["actual_tool_calls"]`` if present (overrides trace extraction).
    2. Tool calls extracted from spans of type ``SpanType.TOOL`` in the trace, using
       the span name and span inputs as the call name and args respectively.
    3. An empty list when neither source is available.
    """
    if expectations and "actual_tool_calls" in expectations:
        return list(expectations["actual_tool_calls"] or [])

    if trace is not None:
        tool_calls = []
        for span in trace.search_spans(span_type=SpanType.TOOL):
            tool_calls.append({"name": span.name, "args": span.inputs})
        return tool_calls

    return []


def _to_function_call(tool_call: Any):
    """Convert a tool-call representation into a Google ADK ``FunctionCall``."""
    from google.genai import types as genai_types

    if isinstance(tool_call, genai_types.FunctionCall):
        return tool_call
    if isinstance(tool_call, dict):
        args = tool_call.get("args")
        if args is not None and not isinstance(args, dict):
            args = {"value": args}
        return genai_types.FunctionCall(name=tool_call.get("name"), args=args)
    # Fall back to attribute access for objects that quack like a function call.
    args = getattr(tool_call, "args", None)
    if args is not None and not isinstance(args, dict):
        args = {"value": args}
    return genai_types.FunctionCall(name=getattr(tool_call, "name", None), args=args)


def map_scorer_inputs_to_invocation(
    inputs: Any = None,
    outputs: Any = None,
    expectations: dict[str, Any] | None = None,
    trace: Trace | None = None,
) -> tuple:
    """Convert MLflow scorer inputs into an (actual, expected) ``Invocation`` pair.

    Args:
        inputs: The input to evaluate.
        outputs: The output to evaluate.
        expectations: Expected values for evaluation.
        trace: MLflow trace for evaluation.

    Returns:
        A tuple of ``(actual_invocation, expected_invocation)`` compatible with the
        Google ADK evaluator interface. When ``expectations`` is absent, the expected
        invocation has ``intermediate_data`` and ``final_response`` set to ``None``.
    """
    from google.adk.evaluation.eval_case import IntermediateData, Invocation
    from google.genai import types as genai_types

    user_content = genai_types.Content(parts=[genai_types.Part(text=_to_text(inputs))])

    # Actual invocation.
    actual_tool_calls = _extract_actual_tool_calls(expectations, trace)
    actual = Invocation(
        user_content=user_content,
        final_response=genai_types.Content(
            parts=[genai_types.Part(text=_to_text(outputs))]
        ),
        intermediate_data=IntermediateData(
            tool_uses=[_to_function_call(tc) for tc in actual_tool_calls]
        ),
    )

    # Expected invocation.
    expected_intermediate_data = None
    expected_final_response = None
    if expectations:
        expected_tool_calls = expectations.get("expected_tool_calls")
        if expected_tool_calls is not None:
            expected_intermediate_data = IntermediateData(
                tool_uses=[_to_function_call(tc) for tc in expected_tool_calls]
            )

        reference = (
            expectations.get("expected_response")
            or expectations.get("reference")
            or expectations.get("context")
        )
        if reference is not None:
            expected_final_response = genai_types.Content(
                parts=[genai_types.Part(text=_to_text(reference))]
            )

    expected = Invocation(
        user_content=user_content,
        final_response=expected_final_response,
        intermediate_data=expected_intermediate_data,
    )

    return actual, expected
